//! Differential test of the lifted field predicates against the verified
//! rewrites of their family.
//!
//! Each rewrite looks at a few fixed fields of its object and returns one when
//! the fields pass a test together (at least one, or all of them), and zero
//! otherwise. The lifted method is `FieldPredicate::evaluate` in `lf-core`,
//! with the fields and combination of the instance.
//!
//! For each instance, CASES objects are built in memory with generated bytes.
//! Each of the instance's fields is zeroed with probability one half, so both
//! answers are reached for every combination. The rewrite is called with the
//! object's address; the lifted method runs on a copy of the same bytes. The
//! results must match, and the object must be unchanged afterwards, since the
//! rewrite only reads it.
//!
//! Wrong versions, each of which every instance must catch: the combination
//! swapped between any and all, the test swapped between nonzero and zero, and
//! the first field moved by its own width.

#![cfg(target_arch = "x86")]

#[path = "support/instances_gen.rs"]
mod instances;

use instances::{INSTANCES, Instance};
use lf_core::field_predicate::{Combine, FieldPredicate, PREDICATES, Test, Width};

/// Generated objects per instance.
const CASES: u32 = 1000;

/// Bytes in one generated object. Every field the rewrites read lies below it.
const OBJECT_BYTES: usize = 0x1280;

/// A deterministic generator (xorshift64), seeded per instance.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    /// Fills `bytes` with generated bytes, eight at a time.
    fn fill(&mut self, bytes: &mut [u8]) {
        for chunk in bytes.chunks_mut(8) {
            let word = self.next().to_le_bytes();
            chunk.copy_from_slice(&word[..chunk.len()]);
        }
    }
}

/// A candidate: the same contract as the lifted method, for one instance.
type Candidate = fn(FieldPredicate<'_>, &[u8]) -> u32;

fn lifted(predicate: FieldPredicate<'_>, object: &[u8]) -> u32 {
    predicate.evaluate(object)
}

fn wrong_combine(predicate: FieldPredicate<'_>, object: &[u8]) -> u32 {
    let mut swapped = predicate;
    swapped.combine = match predicate.combine {
        Combine::Any => Combine::All,
        Combine::All => Combine::Any,
    };
    swapped.evaluate(object)
}

fn wrong_test(predicate: FieldPredicate<'_>, object: &[u8]) -> u32 {
    let mut swapped = predicate;
    swapped.test = match predicate.test {
        Test::NonZero => Test::Zero,
        Test::Zero => Test::NonZero,
    };
    swapped.evaluate(object)
}

fn wrong_first_field_moved(predicate: FieldPredicate<'_>, object: &[u8]) -> u32 {
    let mut moved: Vec<usize> = predicate.offsets.to_vec();
    moved[0] += predicate.width.bytes();
    let shifted = FieldPredicate {
        offsets: &moved,
        ..predicate
    };
    shifted.evaluate(object)
}

/// The fields of the instance: the lifted entry for the same index.
fn predicate_of(index: usize) -> FieldPredicate<'static> {
    PREDICATES[index]
}

/// The first mismatch of a candidate against the instance's rewrite, if any.
fn first_mismatch(
    instance: &Instance,
    predicate: FieldPredicate<'_>,
    candidate: Candidate,
    seed: u64,
) -> Option<String> {
    let mut rng = Rng(seed);
    for case in 0..CASES {
        let mut object = vec![0u8; OBJECT_BYTES];
        rng.fill(&mut object);
        for &offset in predicate.offsets {
            if rng.next() % 2 == 0 {
                for byte in &mut object[offset..offset + predicate.width.bytes()] {
                    *byte = 0;
                }
            }
        }

        let before = object.clone();
        let returned = (instance.call)(object.as_ptr() as usize as u32);
        if object != before {
            return Some(format!(
                "{} case {}: the rewrite changed the object, which it must only read",
                instance.address, case
            ));
        }
        let expected = candidate(predicate, &before);
        if returned != expected {
            return Some(format!(
                "{} case {}: rewrite returned {}, lift returned {}",
                instance.address, case, returned, expected
            ));
        }
    }
    None
}

macro_rules! instance_test {
    ($name:ident, $index:expr) => {
        #[test]
        fn $name() {
            let instance = &INSTANCES[$index];
            let predicate = predicate_of($index);
            let seed = 0x5851_F42D_4C95_7F2D ^ ($index as u64 + 1);
            if let Some(message) = first_mismatch(instance, predicate, lifted, seed) {
                panic!("lifted method differs from the rewrite: {message}");
            }
            assert!(
                first_mismatch(instance, predicate, wrong_combine, seed).is_some(),
                "wrong version (combination swapped) was not caught for {}",
                instance.address
            );
            assert!(
                first_mismatch(instance, predicate, wrong_test, seed).is_some(),
                "wrong version (test swapped) was not caught for {}",
                instance.address
            );
            assert!(
                first_mismatch(instance, predicate, wrong_first_field_moved, seed).is_some(),
                "wrong version (first field moved) was not caught for {}",
                instance.address
            );
        }
    };
}

instance_test!(t_fn_0099f630, 0);
instance_test!(t_fn_0099f6e0, 1);
instance_test!(t_fn_0096bce0, 2);
instance_test!(t_fn_00a29d30, 3);
instance_test!(t_fn_008d8ef0, 4);
instance_test!(t_fn_00ca28f0, 5);

#[test]
fn the_width_of_the_table_entries_is_recorded() {
    assert_eq!(PREDICATES[2].width, Width::Byte);
    assert_eq!(PREDICATES[5].offsets.len(), 3);
}
